export function getBibliaEntryForDayAndYear(dayNumber: number, year: 1 | 2 | 3 | 4 = 1): BibliaYearEntry {
  const dayObj = BIBLIA365_FOUR_YEARS_DATA[dayNumber] || BIBLIA365_FOUR_YEARS_DATA[1];
  return dayObj[`year${year}`] || dayObj.year1;
}

export function getBibliaFourYearsForDay(dayNumber: number): BibliaDayFourYears {
  return BIBLIA365_FOUR_YEARS_DATA[dayNumber] || BIBLIA365_FOUR_YEARS_DATA[1];
}
